import { describe, expect, it } from 'vitest';
import { createPostProcessor, END_BEGINS, kiriExtrudeAbs, START_DONE } from './postprocess';

const kiri = [
  '; Generated by Kiri:Moto 4.7.4',
  'G90',
  'M83',
  'M106 S0 ; a fan line in the start code',
  START_DONE,
  'G1 E-2.5000 F2400 ; e-retract 2.5',
  ';; --- layer 0 (0.200 @ 0.2) ---',
  'M106 S0',
  'G0 Z0.2',
  'G1 X10 Y10 E0.5',
  ';; --- layer 1 (0.200 @ 0.4) ---',
  'G0 Z0.4',
  'G1 X10 Y20 E0.5',
  ';; --- layer 2 (0.200 @ 0.6) ---',
  'M107',
  'm106 S255 ',
  'G1 X10 Y30 E0.5',
  END_BEGINS,
  'M107; Fan off',
  'M84',
];

function run(lines: string[], extrudeAbs = false) {
  const out: string[] = [];
  const post = createPostProcessor({ extrudeAbs }, (line) => out.push(line));
  for (const line of lines) post.line(line);
  return { out, summary: post.summary() };
}

describe('createPostProcessor', () => {
  it('states the extruder mode and turns the fan off right after the start code', () => {
    const { out } = run(kiri);
    const at = out.indexOf(START_DONE);
    expect(out.slice(at + 1, at + 3)).toEqual(['M83 ; relative extrusion for the sliced part', 'M107 ; part fan off for the first layer']);
    expect(run(kiri, true).out[at + 1]).toBe('M82 ; absolute extrusion for the sliced part');
  });

  it('turns the part fan on at the second layer, before its first move', () => {
    const { out } = run(kiri);
    const at = out.indexOf(';; --- layer 1 (0.200 @ 0.4) ---');
    expect(out[at + 1]).toBe('M106 S255 ; part fan on from layer 2');
    expect(out.filter((line) => line.startsWith('M106 S255'))).toHaveLength(1);
  });

  it("drops the slicer's own fan lines between the start and end code, and keeps them elsewhere", () => {
    const { out } = run(kiri);
    expect(out).toContain('M106 S0 ; a fan line in the start code');
    expect(out).toContain('M107; Fan off');
    const body = out.slice(out.indexOf(START_DONE) + 3, out.indexOf(END_BEGINS));
    expect(body.filter((line) => /^m10[67]/i.test(line))).toEqual(['M106 S255 ; part fan on from layer 2']);
  });

  it('keeps every other line, in order, without Windows line ends', () => {
    const { out } = run(kiri.map((line) => `${line}\r`));
    const ours = /(sliced part|first layer|from layer 2)$/;
    const kept = kiri.filter((line, i) => {
      const inBody = i > kiri.indexOf(START_DONE) && i < kiri.indexOf(END_BEGINS);
      return !(inBody && /^\s*m10[67]/i.test(line));
    });
    expect(out.filter((line) => !ours.test(line))).toEqual(kept);
  });

  it('reports the layers and whether both markers were seen', () => {
    expect(run(kiri).summary).toEqual({ layers: 3, fanOn: true, sawStart: true, sawEnd: true });
    expect(run(kiri.filter((line) => line !== START_DONE)).summary).toEqual({
      layers: 0,
      fanOn: false,
      sawStart: false,
      sawEnd: false,
    });
  });
});

describe('kiriExtrudeAbs', () => {
  it("follows Kiri's rule: the device setting, unless the start code sets the mode", () => {
    expect(kiriExtrudeAbs({ extrudeAbs: true, gcodePre: ['G28'] })).toBe(true);
    expect(kiriExtrudeAbs({ extrudeAbs: false, gcodePre: ['G90', 'G28'] })).toBe(true);
    expect(kiriExtrudeAbs({ extrudeAbs: true, gcodePre: ['G90', 'M83'] })).toBe(false);
    expect(kiriExtrudeAbs({ extrudeAbs: false, gcodePre: [' M82 ; absolute', 'G91'] })).toBe(true);
  });
});
